  [215816] = { "Una tesi incompleta secondo cui i ragni sarebbero innocui, ma pur sempre un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0x47e29bf8, "u" },
  [215817] = { "Uno strano testo in difesa dei demoni, eppure un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0x2686007f, "u" },
  [215820] = { "Racconti tanto spaventosi da terrorizzare anche il più temprato dei guerrieri. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0xcffa9914, "u" },
  [215822] = { "Gli strani passi sono sbiaditi ma in parte leggibili, nonostante i danni dell'acqua. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0xcdd80368, "u" },
  [215824] = { "Contiene consigli utili per tenere gli imp da compagnia lontani dai tuoi reagenti. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0xc04a8d53, "u" },
